#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 5e5 + 5;

int n, m, head[N], dis[N], tot[N], cnt;
bool vis[N];
struct
{
	int v, w, next;
} e[N << 1];

void add(int u, int v, int w)
{
	e[++cnt] = {v, w, head[u]};
	head[u] = cnt;
}

void init() {}

bool spfa(int s)
{
	queue<int> q;
	vis[s] = 1;
	q.push(s);
	memset(dis, 0x3f, sizeof dis);
	dis[s] = 0;
	for (int u; q.size();)
	{
		u = q.front();
		q.pop();
		if (vis[u])
			continue;
		for (int i = head[u], v; i; i = e[i].next)
		{
			if (dis[v = e[i].v] > dis[u] + e[i].w)
			{
				dis[v] = dis[u] + e[i].w;
				if (!vis[v])
				{
					vis[v] = 1;
					q.push(v);
					if (++tot[v] > n)
						return 0;
				}
			}
		}
	}
	return 1;
}

void solve()
{
	cin >> n >> m;
	cnt = 0;
	for (int i = 1; i <= n; ++i)
		head[i] = 0;
	for (int i = 1, l, r; i <= m; ++i)
	{
		cin >> l >> r;
		add(l, r, 2);
		add(r, l, 2);
	}
	for (int i = 1; i < n; ++i)
		add(i, i + 1, 0);
	add(n + 1, n + 2, 1);
	add(n + 2, n + 1, 1);
	for (int i = 1; i <= n; ++i)
		add(n + 1, i, 0), add(i, n + 2, 0);
	cout << ((spfa(n + 1)) ? "Yes" : "No") << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}
### Problem Statement

You are given an integer $N$, and $M$ pairs of integers $(L_1,R_1),(L_2,R_2),\ldots,(L_M,R_M)$ satisfying $1\leq L_i<R_i\leq N$.

Determine whether there exists a length-$N$ sequence of $0$s and $1$s, $x=(x_1,x_2,\ldots,x_N)$, that satisfies all of the following conditions.

-   $x_{L_i}+x_{L_i+1}+\cdots+x_{R_i}=2$ for every $i=1,2,\ldots,M$.

You are given $T$ test cases; solve each of them.
### Constraints

-   $1\leq T\leq 250000$
-   $2\leq N\leq 500000$
-   $1\leq M\leq 500000$
-   $1\leq L_i<R_i\leq N$ $(1 \leq i \leq M)$
-   The sum of $N$ over all test cases is at most $500000$.
-   The sum of $M$ over all test cases is at most $500000$.
-   All input values are integers.

